css:
/* Data & Charts Collection V2: Single-Color Tonal Animations
   Palette: #3B82F6 (blue) at 5 opacity levels
   All animations use dc- prefix with per-element stagger */

.si-anim svg { overflow: visible; }

/* ━━━ GLOBAL FILL OVERRIDE: defeat .collection-detail__icon-preview svg { fill: none } cascade ━━━ */
/* scatter-plot dots */
.vd12s5 circle { fill: #3B82F6 !important; stroke: none !important; }
.vd12s5 .dc-dot-1 { fill-opacity: 0.66 !important; }
.vd12s5 .dc-dot-2 { fill-opacity: 0.99 !important; }
.vd12s5 .dc-dot-3 { fill-opacity: 0.88 !important; }
.vd12s5 .dc-dot-4 { fill-opacity: 1 !important; }
.vd12s5 .dc-dot-5 { fill-opacity: 1 !important; }
.vd12s5 .dc-dot-6 { fill-opacity: 1 !important; }
.vd12s5 .dc-dot-7 { fill-opacity: 0.77 !important; }
/* horizontal-chart bars */
.pmtnx4 rect { fill: #3B82F6 !important; stroke: none !important; }
.pmtnx4 .dc-bar-1 { fill-opacity: 1 !important; }
.pmtnx4 .dc-bar-2 { fill-opacity: 1 !important; }
.pmtnx4 .dc-bar-3 { fill-opacity: 0.77 !important; }
/* candlestick bodies */
.g3qlje rect { fill: #3B82F6 !important; stroke: none !important; }
.g3qlje .dc-body-1 { fill-opacity: 0.77 !important; }
.g3qlje .dc-body-2 { fill-opacity: 1 !important; }
.g3qlje .dc-body-3 { fill-opacity: 1 !important; }
.g3qlje .dc-body-4 { fill-opacity: 1 !important; }
/* histogram bars */
.kh27p9 rect { fill: #3B82F6 !important; stroke: none !important; }
.kh27p9 .dc-bar-1 { fill-opacity: 0.55 !important; }
.kh27p9 .dc-bar-2 { fill-opacity: 0.88 !important; }
.kh27p9 .dc-bar-3 { fill-opacity: 1 !important; }
.kh27p9 .dc-bar-4 { fill-opacity: 1 !important; }
.kh27p9 .dc-bar-5 { fill-opacity: 1 !important; }
.kh27p9 .dc-bar-6 { fill-opacity: 0.66 !important; }
/* treemap blocks */
.uv7an2 rect { fill: #3B82F6 !important; stroke: none !important; }
.uv7an2 .dc-frame { fill: none !important; stroke: #3B82F6 !important; stroke-opacity: 0.38 !important; stroke-width: 1 !important; }
.uv7an2 .dc-block-1 { fill-opacity: 1 !important; }
.uv7an2 .dc-block-2 { fill-opacity: 0.85 !important; }
.uv7an2 .dc-block-3 { fill-opacity: 0.7 !important; }
.uv7an2 .dc-block-4 { fill-opacity: 0.55 !important; }
.uv7an2 .dc-block-5 { fill-opacity: 0.85 !important; }
.uv7an2 .dc-block-6 { fill-opacity: 0.44 !important; }

/* ━━━ 1. BAR CHART: bars bounce staggered on hover ━━━ */
.zhe4xf .dc-bar { transition: transform .3s ease, fill-opacity .3s ease; }
.si-icon-cell:hover .zhe4xf .dc-bar-1,
.icon-card:hover .zhe4xf .dc-bar-1 { animation: r90bk2 .4s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .zhe4xf .dc-bar-2,
.icon-card:hover .zhe4xf .dc-bar-2 { animation: r90bk2 .4s cubic-bezier(.34,1.56,.64,1) .08s forwards; }
.si-icon-cell:hover .zhe4xf .dc-bar-3,
.icon-card:hover .zhe4xf .dc-bar-3 { animation: r90bk2 .4s cubic-bezier(.34,1.56,.64,1) .16s forwards; }

/* ━━━ 2. LINE CHART: dots scale up, line brightens ━━━ */
.m3jmej .dc-dot { transition: transform .25s ease, fill-opacity .25s ease; }
.m3jmej .dc-line { transition: stroke-opacity .3s ease; }
.si-icon-cell:hover .m3jmej .dc-line,
.icon-card:hover .m3jmej .dc-line { stroke-opacity: 0.9; }
.si-icon-cell:hover .m3jmej .dc-dot-1,
.icon-card:hover .m3jmej .dc-dot-1 { animation: rsddo2 .3s ease forwards; }
.si-icon-cell:hover .m3jmej .dc-dot-2,
.icon-card:hover .m3jmej .dc-dot-2 { animation: rsddo2 .3s ease .06s forwards; }
.si-icon-cell:hover .m3jmej .dc-dot-3,
.icon-card:hover .m3jmej .dc-dot-3 { animation: rsddo2 .3s ease .12s forwards; }
.si-icon-cell:hover .m3jmej .dc-dot-4,
.icon-card:hover .m3jmej .dc-dot-4 { animation: rsddo2 .3s ease .18s forwards; }
.si-icon-cell:hover .m3jmej .dc-dot-5,
.icon-card:hover .m3jmej .dc-dot-5 { animation: rsddo2 .3s ease .24s forwards; }

/* ━━━ 3. PIE CHART: slices explode outward with bounce ━━━ */
.aejj68 .dc-slice { transform-origin: 12px 12px; }
.si-icon-cell:hover .aejj68 .dc-slice-1,
.icon-card:hover .aejj68 .dc-slice-1 { animation: odo17r .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .aejj68 .dc-slice-2,
.icon-card:hover .aejj68 .dc-slice-2 { animation: etj7x3 .5s cubic-bezier(.34,1.56,.64,1) .06s forwards; }
.si-icon-cell:hover .aejj68 .dc-slice-3,
.icon-card:hover .aejj68 .dc-slice-3 { animation: x5kffy .5s cubic-bezier(.34,1.56,.64,1) .12s forwards; }

/* ━━━ 4. DONUT CHART: ring spins, arcs pulse staggered ━━━ */
/* Force stroke values on all paths - defeats global cascade */
.jwmqiz path { stroke: #3B82F6 !important; stroke-width: 4.5 !important; fill: none !important; }
.jwmqiz .dc-arc-1 { stroke-opacity: 0.45 !important; }
.jwmqiz .dc-arc-2 { stroke-opacity: 0.72 !important; }
.jwmqiz .dc-arc-3 { stroke-opacity: 1 !important; }
.imjihk .dc-arc { transform-origin: 12px 12px; }
.si-icon-cell:hover .imjihk svg,
.icon-card:hover .imjihk svg { animation: vrnaif .6s ease forwards; }
.si-icon-cell:hover .imjihk .dc-arc-1,
.icon-card:hover .imjihk .dc-arc-1 { animation: uwxd5e .4s ease forwards; }
.si-icon-cell:hover .imjihk .dc-arc-2,
.icon-card:hover .imjihk .dc-arc-2 { animation: uwxd5e .4s ease .1s forwards; }
.si-icon-cell:hover .imjihk .dc-arc-3,
.icon-card:hover .imjihk .dc-arc-3 { animation: uwxd5e .4s ease .2s forwards; }

/* ━━━ 5. AREA CHART: fill rises from baseline, line draws, peak bounces ━━━ */
.k1k4ap .dc-area { transform-origin: center bottom; }
.si-icon-cell:hover .k1k4ap .dc-area,
.icon-card:hover .k1k4ap .dc-area { animation: mqg0nu .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .k1k4ap .dc-line,
.icon-card:hover .k1k4ap .dc-line { animation: qnvxwz .4s ease forwards; }
.si-icon-cell:hover .k1k4ap .dc-peak,
.icon-card:hover .k1k4ap .dc-peak { animation: b9amdj .4s cubic-bezier(.34,1.56,.64,1) .2s forwards; transform-origin: 21px 7px; }

/* ━━━ 6. SCATTER PLOT: dots scatter then settle ━━━ */
.hg4wk2 .dc-dot { opacity: 1; transform: scale(1); transform-origin: center; }
.si-icon-cell:hover .hg4wk2 .dc-dot-1,
.icon-card:hover .hg4wk2 .dc-dot-1 { animation: eybuvc .3s ease forwards; }
.si-icon-cell:hover .hg4wk2 .dc-dot-2,
.icon-card:hover .hg4wk2 .dc-dot-2 { animation: eybuvc .3s ease .05s forwards; }
.si-icon-cell:hover .hg4wk2 .dc-dot-3,
.icon-card:hover .hg4wk2 .dc-dot-3 { animation: eybuvc .3s ease .1s forwards; }
.si-icon-cell:hover .hg4wk2 .dc-dot-4,
.icon-card:hover .hg4wk2 .dc-dot-4 { animation: eybuvc .3s ease .15s forwards; }
.si-icon-cell:hover .hg4wk2 .dc-dot-5,
.icon-card:hover .hg4wk2 .dc-dot-5 { animation: eybuvc .3s ease .2s forwards; }
.si-icon-cell:hover .hg4wk2 .dc-dot-6,
.icon-card:hover .hg4wk2 .dc-dot-6 { animation: eybuvc .3s ease .25s forwards; }
.si-icon-cell:hover .hg4wk2 .dc-dot-7,
.icon-card:hover .hg4wk2 .dc-dot-7 { animation: eybuvc .3s ease .3s forwards; }

/* ━━━ 7. HORIZONTAL CHART: bars surge right then snap back ━━━ */
.hed5zr .dc-bar { transform: scaleX(1); transform-origin: left; }
.si-icon-cell:hover .hed5zr .dc-bar-1,
.icon-card:hover .hed5zr .dc-bar-1 { animation: kib45q .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .hed5zr .dc-bar-2,
.icon-card:hover .hed5zr .dc-bar-2 { animation: kib45q .5s cubic-bezier(.34,1.56,.64,1) .08s forwards; }
.si-icon-cell:hover .hed5zr .dc-bar-3,
.icon-card:hover .hed5zr .dc-bar-3 { animation: kib45q .5s cubic-bezier(.34,1.56,.64,1) .16s forwards; }

/* ━━━ 8. CANDLESTICK: live price tick - alternating up/down movement ━━━ */
.xwmzxg .dc-body { transform: scaleY(1); transform-origin: center; }
.xwmzxg .dc-wick { stroke-dasharray: 15; stroke-dashoffset: 0; }
.si-icon-cell:hover .xwmzxg .dc-body-1,
.icon-card:hover .xwmzxg .dc-body-1 { animation: uq7udz .45s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .xwmzxg .dc-body-2,
.icon-card:hover .xwmzxg .dc-body-2 { animation: ep7t7i .45s cubic-bezier(.34,1.56,.64,1) .08s forwards; }
.si-icon-cell:hover .xwmzxg .dc-body-3,
.icon-card:hover .xwmzxg .dc-body-3 { animation: uq7udz .45s cubic-bezier(.34,1.56,.64,1) .16s forwards; }
.si-icon-cell:hover .xwmzxg .dc-body-4,
.icon-card:hover .xwmzxg .dc-body-4 { animation: ep7t7i .45s cubic-bezier(.34,1.56,.64,1) .24s forwards; }
.si-icon-cell:hover .xwmzxg .dc-wick,
.icon-card:hover .xwmzxg .dc-wick { animation: jy2rzt .4s ease .1s forwards; }

/* ━━━ 9. HISTOGRAM: wave crest ripples from center outward ━━━ */
.g255bx .dc-bar { transform: scaleY(1); transform-origin: bottom; }
.si-icon-cell:hover .g255bx .dc-bar-1,
.icon-card:hover .g255bx .dc-bar-1 { animation: eggkue .5s cubic-bezier(.34,1.56,.64,1) .2s forwards; }
.si-icon-cell:hover .g255bx .dc-bar-2,
.icon-card:hover .g255bx .dc-bar-2 { animation: eggkue .5s cubic-bezier(.34,1.56,.64,1) .1s forwards; }
.si-icon-cell:hover .g255bx .dc-bar-3,
.icon-card:hover .g255bx .dc-bar-3 { animation: eggkue .5s cubic-bezier(.34,1.56,.64,1) 0s forwards; }
.si-icon-cell:hover .g255bx .dc-bar-4,
.icon-card:hover .g255bx .dc-bar-4 { animation: eggkue .5s cubic-bezier(.34,1.56,.64,1) .05s forwards; }
.si-icon-cell:hover .g255bx .dc-bar-5,
.icon-card:hover .g255bx .dc-bar-5 { animation: eggkue .5s cubic-bezier(.34,1.56,.64,1) .15s forwards; }
.si-icon-cell:hover .g255bx .dc-bar-6,
.icon-card:hover .g255bx .dc-bar-6 { animation: eggkue .5s cubic-bezier(.34,1.56,.64,1) .25s forwards; }

/* ━━━ 10. TREEMAP: tiles cascade in ━━━ */
.u8vgov .dc-block { opacity: 1; transform: scale(1); }
.si-icon-cell:hover .u8vgov .dc-block-1,
.icon-card:hover .u8vgov .dc-block-1 { animation: y6q11t .3s ease forwards; }
.si-icon-cell:hover .u8vgov .dc-block-2,
.icon-card:hover .u8vgov .dc-block-2 { animation: y6q11t .3s ease .06s forwards; }
.si-icon-cell:hover .u8vgov .dc-block-3,
.icon-card:hover .u8vgov .dc-block-3 { animation: y6q11t .3s ease .12s forwards; }
.si-icon-cell:hover .u8vgov .dc-block-4,
.icon-card:hover .u8vgov .dc-block-4 { animation: y6q11t .3s ease .18s forwards; }
.si-icon-cell:hover .u8vgov .dc-block-5,
.icon-card:hover .u8vgov .dc-block-5 { animation: y6q11t .3s ease .24s forwards; }
.si-icon-cell:hover .u8vgov .dc-block-6,
.icon-card:hover .u8vgov .dc-block-6 { animation: y6q11t .3s ease .3s forwards; }

/* ━━━ 11. TRENDING UP: line pulses glow + shifts upward ━━━ */
.mjqwll .dc-line { stroke-dasharray: 30; stroke-dashoffset: 0; }
.mjqwll .dc-arrow { stroke-dasharray: 12; stroke-dashoffset: 0; }
.si-icon-cell:hover .mjqwll .dc-line,
.icon-card:hover .mjqwll .dc-line { animation: maoqrh .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .mjqwll .dc-arrow,
.icon-card:hover .mjqwll .dc-arrow { animation: maoqrh .4s cubic-bezier(.34,1.56,.64,1) .1s forwards; }
.si-icon-cell:hover .mjqwll svg,
.icon-card:hover .mjqwll svg { filter: drop-shadow(0 0 4px rgba(59,130,246,.5)); }

/* ━━━ 12. TRENDING DOWN: line pulses glow + shifts downward ━━━ */
.ts9r1n .dc-line { stroke-dasharray: 30; stroke-dashoffset: 0; }
.ts9r1n .dc-arrow { stroke-dasharray: 12; stroke-dashoffset: 0; }
.si-icon-cell:hover .ts9r1n .dc-line,
.icon-card:hover .ts9r1n .dc-line { animation: pueprw .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .ts9r1n .dc-arrow,
.icon-card:hover .ts9r1n .dc-arrow { animation: pueprw .4s cubic-bezier(.34,1.56,.64,1) .1s forwards; }
.si-icon-cell:hover .ts9r1n svg,
.icon-card:hover .ts9r1n svg { filter: drop-shadow(0 0 4px rgba(59,130,246,.4)); }

/* ━━━ 13. GAUGE: needle sweeps ━━━ */
.dhelx3 .dc-needle { transform: rotate(-90deg); transform-origin: 12px 18px; }
.si-icon-cell:hover .dhelx3 .dc-needle,
.icon-card:hover .dhelx3 .dc-needle { animation: fwq21j .6s cubic-bezier(.34,1.56,.64,1) forwards; }

/* ━━━ 14. PERCENTAGE: arc fills ━━━ */
.aq50cx .dc-progress { stroke-dasharray: 0 56.55; }
.si-icon-cell:hover .aq50cx .dc-progress,
.icon-card:hover .aq50cx .dc-progress { animation: u25c6h .7s ease forwards; }

/* ━━━ 15. COUNTER: digits ticker ━━━ */
.a5s2pb .dc-digit { transform: translateY(4px); opacity: 0; }
.si-icon-cell:hover .a5s2pb .dc-digit-1,
.icon-card:hover .a5s2pb .dc-digit-1 { animation: yo50dx .3s ease forwards; }
.si-icon-cell:hover .a5s2pb .dc-digit-2,
.icon-card:hover .a5s2pb .dc-digit-2 { animation: yo50dx .3s ease .1s forwards; }
.si-icon-cell:hover .a5s2pb .dc-digit-3,
.icon-card:hover .a5s2pb .dc-digit-3 { animation: yo50dx .3s ease .2s forwards; }

/* ━━━ 16. KPI CARD: value bounces, sparkline glows ━━━ */
.k1zwps .dc-value { opacity: 1; transform: scale(1); }
.k1zwps .dc-sparkline { stroke-dasharray: 30; stroke-dashoffset: 0; }
.si-icon-cell:hover .k1zwps .dc-value,
.icon-card:hover .k1zwps .dc-value { animation: xezpe5 .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .k1zwps .dc-sparkline,
.icon-card:hover .k1zwps .dc-sparkline { animation: zpvagm .4s ease .1s forwards; }
.si-icon-cell:hover .k1zwps .dc-indicator,
.icon-card:hover .k1zwps .dc-indicator { animation: maoqrh .4s cubic-bezier(.34,1.56,.64,1) forwards; }

/* ━━━ 17. COMPARISON: bars compete with surge bounce ━━━ */
.n226s5 .dc-bar { transform: scaleY(1); transform-origin: bottom; }
.si-icon-cell:hover .n226s5 .dc-bar-a1,
.icon-card:hover .n226s5 .dc-bar-a1 { animation: eggkue .45s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .n226s5 .dc-bar-b1,
.icon-card:hover .n226s5 .dc-bar-b1 { animation: eggkue .45s cubic-bezier(.34,1.56,.64,1) .06s forwards; }
.si-icon-cell:hover .n226s5 .dc-bar-a2,
.icon-card:hover .n226s5 .dc-bar-a2 { animation: eggkue .45s cubic-bezier(.34,1.56,.64,1) .18s forwards; }
.si-icon-cell:hover .n226s5 .dc-bar-b2,
.icon-card:hover .n226s5 .dc-bar-b2 { animation: eggkue .45s cubic-bezier(.34,1.56,.64,1) .24s forwards; }

/* ━━━ 18. DELTA: arrow bounces ━━━ */
.vhbh68 .dc-arrow, .vhbh68 .dc-arrow-head { transform: translateY(6px); opacity: 0; }
.si-icon-cell:hover .vhbh68 .dc-arrow,
.icon-card:hover .vhbh68 .dc-arrow,
.si-icon-cell:hover .vhbh68 .dc-arrow-head,
.icon-card:hover .vhbh68 .dc-arrow-head { animation: ezzyfz .5s cubic-bezier(.34,1.56,.64,1) forwards; }

/* ━━━ 19. TARGET: rings pulse inward ━━━ */
.g470sl .dc-ring { opacity: 1; transform: scale(1); transform-origin: 12px 12px; }
.g470sl .dc-bullseye { opacity: 1; transform: scale(1); transform-origin: 12px 12px; }
.si-icon-cell:hover .g470sl .dc-ring-1,
.icon-card:hover .g470sl .dc-ring-1 { animation: yfu86o .6s ease forwards; }
.si-icon-cell:hover .g470sl .dc-ring-2,
.icon-card:hover .g470sl .dc-ring-2 { animation: yfu86o .6s ease .1s forwards; }
.si-icon-cell:hover .g470sl .dc-ring-3,
.icon-card:hover .g470sl .dc-ring-3 { animation: yfu86o .6s ease .2s forwards; }
.si-icon-cell:hover .g470sl .dc-bullseye,
.icon-card:hover .g470sl .dc-bullseye { animation: eicuyt .5s cubic-bezier(.34,1.56,.64,1) .15s forwards; }

/* ━━━ 20. SCORE: badge scales, center pops ━━━ */
.zc6fdj .dc-badge { opacity: 0; transform: scale(.5); transform-origin: 12px 12px; }
.zc6fdj .dc-center { opacity: 0; }
.si-icon-cell:hover .zc6fdj .dc-badge,
.icon-card:hover .zc6fdj .dc-badge { animation: wqdvrs .4s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .zc6fdj .dc-center,
.icon-card:hover .zc6fdj .dc-center { animation: ikmub3 .3s ease .3s forwards; }

/* ━━━ 21. TABLE: rows slide in staggered ━━━ */
.j52uf2 .dc-row { transform: translateX(-8px); opacity: 0; }
.si-icon-cell:hover .j52uf2 .dc-row-1,
.icon-card:hover .j52uf2 .dc-row-1 { animation: rattdm .3s ease forwards; }
.si-icon-cell:hover .j52uf2 .dc-row-2,
.icon-card:hover .j52uf2 .dc-row-2 { animation: rattdm .3s ease .1s forwards; }
.si-icon-cell:hover .j52uf2 .dc-row-3,
.icon-card:hover .j52uf2 .dc-row-3 { animation: rattdm .3s ease .2s forwards; }

/* ━━━ 22. GRID VIEW: cells tile cascade ━━━ */
.pelqtk .dc-cell { opacity: 1; transform: scale(1); }
.si-icon-cell:hover .pelqtk .dc-cell-1, .icon-card:hover .pelqtk .dc-cell-1 { animation: j084h8 .35s ease forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-2, .icon-card:hover .pelqtk .dc-cell-2 { animation: j084h8 .35s ease .04s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-3, .icon-card:hover .pelqtk .dc-cell-3 { animation: j084h8 .35s ease .08s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-4, .icon-card:hover .pelqtk .dc-cell-4 { animation: j084h8 .35s ease .12s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-5, .icon-card:hover .pelqtk .dc-cell-5 { animation: j084h8 .35s ease .16s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-6, .icon-card:hover .pelqtk .dc-cell-6 { animation: j084h8 .35s ease .2s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-7, .icon-card:hover .pelqtk .dc-cell-7 { animation: j084h8 .35s ease .24s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-8, .icon-card:hover .pelqtk .dc-cell-8 { animation: j084h8 .35s ease .28s forwards; }
.si-icon-cell:hover .pelqtk .dc-cell-9, .icon-card:hover .pelqtk .dc-cell-9 { animation: j084h8 .35s ease .32s forwards; }

/* ━━━ 23. DATABASE: layers stack ━━━ */
.wb54ui .dc-lid { transform: translateY(0); opacity: 1; }
.wb54ui .dc-body { opacity: 1; }
.wb54ui .dc-base { opacity: 1; }
.si-icon-cell:hover .wb54ui .dc-lid, .icon-card:hover .wb54ui .dc-lid { animation: s8sn2o .5s cubic-bezier(.34,1.56,.64,1) forwards; }
.si-icon-cell:hover .wb54ui .dc-body, .icon-card:hover .wb54ui .dc-body { animation: p5r6wu .4s ease .1s forwards; }
.si-icon-cell:hover .wb54ui .dc-accent, .icon-card:hover .wb54ui .dc-accent { animation: eicuyt .5s cubic-bezier(.34,1.56,.64,1) forwards; }

/* ━━━ 24. SPREADSHEET: active cell pulses ━━━ */
.c6p5uh .dc-active { opacity: 0; }
.si-icon-cell:hover .c6p5uh .dc-active,
.icon-card:hover .c6p5uh .dc-active { animation: isfuyk .6s ease infinite; }

/* ━━━ 25. DATA FLOW: nodes pulse radially, connectors shimmer ━━━ */
.pc2h65 .dc-node { opacity: 1; transform: scale(1); }
